"iwujvz": "你为{0}勾选了“总是用它飞”。按下后，选择界面会在每张地图再次询问。",
"stn2d9": "摇杆能打多远、有多灵敏。这是你自己的，不属于调参。Acro 模式的遥控器按这条曲线飞；键盘比赛以 Angle 模式开始。在一局中途更改，穿越机留在原地，计时继续。",
"1m2xvti": "飞行模式",
"xjyq13": "Acro：摇杆控制角速度，松手保持姿态。Angle：摇杆控制倾角，最大到 Betaflight 的 60 度上限，松手自动回平。这场比赛用键盘飞，键盘有它自己的选择（机型里的“键盘比赛”）；这一行改的就是那个。飞行中按 M 也能切换。",
"1r5ubv6": "Acro：摇杆控制角速度，松手保持姿态。Angle：摇杆控制倾角，最大到 Betaflight 的 60 度上限，松手自动回平，偏航仍是角速度。翻滚动作需要 Acro。飞行中按 M 也能切换，并会保存。",
"x7vih9": "每边几个人、机器人水平如何、什么时候结束。",
