"1sc5qgc": "你的名字、遥控器、画质和声音。",
"6gxuho": "结束{0}。",
"wyh1np": "穿越机感觉有多重。往右更重：收油门时会往下掉，也不会在跳跃顶点悬住。往左更轻，会飘起来。{0}是出厂状态；一圈中途更改会让这一圈作废，不在{1}下飞的圈会带着重量标在你名字旁上公共榜单。",
"1ayl725": "空气抓力",
"6bttpz": "空气把穿越机拉住多少，也就是摇杆回中后它还能滑多远。往左会一直滑行并且更快；往右空气抓住它，停得更早，极速也更低。{0}是出厂状态，根据飞手们发来的调参设定。一圈中途更改会让这一圈作废，不在{1}下飞的圈会带“Tuned”标签发到公共榜单。",
"ior56v": "电机动力",
"1x4irmq": "电机每伏电压转多快，也就是 KV。往左更柔：推力更温和，极速更低。往右更猛，电池压降也更大，悬停点在摇杆上更低。{0}是出厂状态，根据飞手们发来的调参设定。一圈中途更改会让这一圈作废，不在{1}下飞的圈会带“Tuned”标签发到公共榜单。",
"1bsvonq": "默认关闭。打开后，穿越机在地面时，{0}会和重量一起出现在摇杆之间；用你自己的滑块飞完一次后会问一个问题：这比原厂穿越机感觉更好吗？除非你回答是，否则什么都不会发送。关闭时，不管滑块怎么设，穿越机都按出厂状态飞。一圈中途切换，如果改变了你正在飞的穿越机，这一圈作废。",
"5xvgod": "调过的飞行结束后询问",
"1siorg1": "用你自己的滑块飞完一次后，问你是否比原厂感觉更好。你随时可以回答否，没有“是”就什么都不会发送。关闭后不再询问；滑块仍然有效。",
"187fv0s": "告诉调参工作这架穿越机飞起来怎么样。一个词就够；你的调参、PID 调整和 Rates 会一起发送。",
