"1yc8yfn": "飞行界面上摇杆之间的重量滑块正是为这个问题准备的：它缩放穿越机的负重，所以收油门时会往下掉而不是悬着。你现在在百分之 {0}。越往右，收油门时掉得越快，短促推油后也飘得越少。悬停点会随它在摇杆上上移，从原厂的百分之 {1} 到 {3} 时的 {2}。等我们之前值得先拖一拖；用它飞的圈会带着重量标在你名字旁上公共榜单。",
"r74boy": "没有油门限制时，这架穿越机在摇杆百分之 {0} 处悬停，所以几乎所有行程都在悬停点之上。Rates、油门限制、百分之 75 会把悬停点移到百分之 {1}，把精细控制找回来，又不损失室内用得上的爬升。等我们之前值得一试。",
"1xpffsm": "打开飞行手感调节",
"194uxup": "飞行手感调节已打开。落地时，{0}{1}在摇杆之间的重量旁边。如果某个设置比原厂感觉更好，飞行结束时会问你要不要发送。",
"1elhpti": "想自己改？飞行手感调节会在你落地时把{0}放在重量旁边：{1}。如果某个设置比原厂感觉更好，你可以在飞行后把数字发给我们。不打开就一直关闭，没有你的“是”就什么都不会发送。",
"15h6xkr": "用你自己的话说（可选）",
"1m200ro": "你想对拿着螺丝刀的那个人说的话。",
"1d67zxc": "穿越机感觉",
"ghfh85": "具体问题（可多选）",
"z5wkkb": "在第一行选一个词。一个就够。",
"1gl4sk7": "这一局穿越机感觉{0}。",
"7ajpz1": "注意到：{0}。",
"1e17m8": "谢谢",
"120kk3i": "收到了，你的调参和 Rates 也一起到了。推动飞行模型的正是这些。",
"frbrff": "调参已发送",
"yigmhv": "那个调参已上榜单。谢谢。",
"1xaroqk": "{0}，空中 {1}。如果比原厂感觉更好，就附上一两句话，把数字发给给模拟器调参的人。不按“发送”就什么都不会发送。",
"12j7air": "这比原厂感觉更好吗？",
"1qjshkq": "{0}。用{2}在空中飞了 {1}。",
"1k9f9e0": "如果是，你可以附上一两句话，把这些数字发给给模拟器调参的人。不在下一个界面按“发送”就什么都不会发送。",
"lmpjg0": "比原厂好",
"kertdk": "一样或更差",
"bhqymg": "不再询问",
"159zlyr": "谢谢，这很有用",
"1v1dzby": "感觉一样或更差的调参能告诉给模拟器调参的人哪条路不该走。想把这个结果也发送吗？你不同意就什么都不会发送。",
"1vcax0y": "发送这个结果",
"13gi980": "发送你的调参",
"pve1j9": "{0}。用{2}在空中飞了 {1}。这些会连同你的话一起发到榜单，按机型和物理版本分组，让给模拟器调参的人看到飞手们喜欢什么。你的调参、Rates 以及飞行手感报告里的同样信息会一起发送。",
"wanvfr": "改了什么，以及你想对拿着螺丝刀的那个人说的话。",
