"11rwvoh": "重新开始本局",
"1du6wdf": "离开房间",
"1kp0jei": "留在这里单人继续飞。",
"1pr2kpr": "同时离开房间。",
"1m53rax": "摇杆能打多远，以及油门上限。这是你自己的，不属于调参。在这里更改，穿越机留在原地，计时继续。",
"iyaaav": "你的最好成绩仍然有效",
"5v8g8h": "成绩已发布",
"zhn0rw": "榜单上已经有你更好的一局，{0}。只保留你的最好成绩。",
"a99h6c": "发布这一局",
"ftm3jn": "没有动作的一局不算分数。做一个动作，它就会出现在这里。",
"87cor7": "自由飞行没有计时，所以榜单没有可以比较的东西。在地图大厅把计分设为计分局，再飞一次。",
"1v6l9n2": "这一局用了测试钩子，所以不是飞出来的分数，榜单不会接收。",
"grcded": "这一局中途重量变了，所以榜单没有一个统一的重量可以显示。用同一个重量再飞一次。",
"tbtfzi": "调过的飞行，不会发布到榜单。在空气抓力或电机动力不是 100 时做出的动作，用的是和其他人不一样的穿越机。把两项都调回 100 再飞一次。",
"1pz4yp7": "{1} 个动作{2}{3}，共 {0}。榜单上每位飞手一条记录，只保留你的最好成绩。",
