"13caij": "保存分享卡",
"3o9ejy": "没有可画内容的一局没有卡片。一个动作、一次穿缝、一次贴飞或一次跟尾就会让它出现在这里。",
"e5ghz6": "已保存为 {0}。再选一次这一行可以再存一份。",
"14yxwli": "把这一局画成一页漫画放在分数旁边，1200×630，就是链接预览用的尺寸。保存为 JPEG，想发到哪里都行。",
"1k0zug5": "所有已发布的赛道和地图，以及在上面飞出的成绩。在新标签页打开。",
