"p5l6b4": "{0}{1}，赛道大厅里的下一条赛道。直接进入起跑位。",
"1qgmzxt": "公共榜单上的{0}，在它自己的页面打开：上面发布的所有成绩和飞手。在新标签页打开。",
"rmebwy": "这条赛道",
