"rf5rfp": "穿越机偏航比横滚慢，所以很多飞手把偏航设得比横滚低。你的相机上仰 {0} 度，所以偏航的百分之 {1} 会让地平线倾斜而不是转向：满舵时画面横滚 {2} deg/s。",
"1jsxhz2": "预设",
"imoqhc": "没有保存",
"14ukk4x": "一个已保存的配置",
"bkhyho": "Rates 类型",
"cdtta": "下面的数字属于哪种 Rates 体系。五种都是 Betaflight 自己的，五种都能飞：曲线由 fc/rc.c 里的这一个字段选择。Actual 是 Betaflight 4.5 的默认值，也是“最大速率”一栏在行程尽头说到做到的那一种。更改它会加载该体系自己的默认值，因为 Betaflight 的 RC rate 1.00 和 Actual 的中心灵敏度 70 存的是同一个数字，却不是同一个设置。",
"1bi0zn2": "俯仰独立",
"3xx6vi": "开。俯仰有自己的三个数字，在图上也有自己的曲线。关闭会把横滚复制到俯仰。",
"c4nhs2": "关。横滚和俯仰共用一组数字，大多数穿越机都这样设置，Betaflight 出厂也是如此。打开它可以给俯仰单独一组。",
"s1apod": "横滚和俯仰",
"16y9oqq": "油门限制",
"18dkbs9": "关。这架穿越机的推重比接近九比一，在摇杆百分之 {0} 处悬停，所以大部分行程都在悬停点之上。加上限制会把整根摇杆按比例缩小，把分辨率找回来。",
"74eytz": "Betaflight 的 SCALE 限制：满杆指令为百分之 {0}，整个行程在它之下重新分配。悬停点移到摇杆的大约百分之 {1}，所以油门没那么敏感。",
"9pydfr": "{0} 按出厂曲线，这架穿越机在摇杆百分之 {1} 附近悬停。",
