"1m38alp": "未保存",
"2xpdfb": "保存为预设",
"1i6mwh9": "删除预设",
"u3znvf": "忘掉{0}。这个浏览器里是唯一的副本，所以无法撤销。数字仍留在穿越机上；消失的只是保存的配置。",
"17l6uak": "请先加载一个预设。这会删除下面各行正在使用的配置，而它们现在用的不是已保存的配置。",
"p52kwi": "恢复默认",
"17l8bg0": "回到自带的 Rates：Actual，中心 {0} deg/s，每个轴行程尽头 {1} deg/s，没有 expo，没有油门限制。比刚刷好的 Betaflight 的 70 和 670 低一档，各差一行。",
"8av510": "已经是自带的默认值。",
"hu0m9h": "{0}以 RP 模式运行滑块，所以它们作用于横滚和俯仰，偏航保持原厂值，和 Configurator 完全一样。",
"x624ug": "{0}出厂时这里是 {1}；调回这个值就会忘掉这次修改。",
