"1bhsb37": "仅用于 3D 飞行。电机可以双向旋转：油门中位没有推力，最低位会让你倒着飞，所以在你回到设置、飞手、3D 模式把它关掉之前，正常飞行会感觉坏掉了。",
"v65w1o": "保持关闭",
"u2bdti": "打开 3D",
"7g0dlj": "在 3D 模式下，油门中位没有推力，最低位会让你倒着飞，所以正常飞行会感觉坏掉了。它很容易被误开。只有飞 3D 时才保持打开。",
"mxrvnc": "关闭 3D",
"1s8d24o": "保持 3D 打开",
"avqznd": "这样飞的圈会带“Tuned”标签发到公共榜单。",
"ohro0a": "真实物理",
"s62yi0": "{0}已开启，实验性：它以真实重量在真实重力下飞行。转动更自由，空气像在户外一样反推桨叶，下洗气流会停留在原处，低空悬停时有地面效应托着，猛推油门时电池压降，花飞时电量会一直消耗到你重置为止。它的转动、电机和电池对照了两架真机的飞行日志；其余部分是推算的，不是实测的。真实物理的圈会单独保留最快圈。{1}关闭它就能让{2}像以前一样飞。一圈中途更改会让这一圈作废。",
"bugmc9": "{0}已关闭：还是它一直以来的飞法。打开它可以体验实验性的真实世界模型：真实的重量和重力、更自由的转动、更真实的桨叶气流、停留在原处的下洗气流、地面效应，以及会压降、在花飞中会耗尽的电池。{1}每架穿越机各自记住自己的选择。",
"qzitkf": "真实物理已开启",
"11c30rz": "5寸机现在用一个实验性的真实世界模型飞行，对照了真机的飞行日志。它和真机一样重，所以悬停点在油门上更低，速度也保持得更久。它转动更自由，电机响应要一点时间，猛推油门时电池会压降。花飞时电池还会耗尽，重置会给你一块新的。你以前的最快圈都保留着，换回旧手感时就会回来。随时可以更改：设置、飞手、真实物理。",
"1cm6jsn": "知道了，起飞",
