"b46ibj": "翻乌龟",
"4uqxss": "如果你倒扣在地上，会出现 TURTLE MODE 提示。在右触控区打俯仰或横滚就能翻过来。不需要掐时机。松开，然后起飞。",
"1qyunph": "右上角的暂停按钮。撞到会弹开。代价是时间。继续后，如果倒扣着就打俯仰或横滚。",
