"lkidd0": "左摇杆（模式 {0}）",
"dgt1q3": "{0}。模式在遥控器上设置；本页在设置里跟随它。",
"1a3en5u": "加载本页之前先把遥控器设为摇杆模式，然后在设置里运行校准摇杆。",
"8pq8oh": "俯仰移动光标，右横滚选择，左横滚返回。暂停或完赛后，让摇杆回中稍等片刻，再把横滚保持一拍。",
"d45qj0": "重新开始",
"ezjsbi": "键盘上的 R，或者遥控器上的一个开关：设置，重启开关，然后拨动它。",
"o7cl2g": "松手会保持你离开时的姿态。每个弯都得自己飞回来。",
"etorb5": "如果你倒扣在地上，会出现 TURTLE MODE 提示。用右摇杆打俯仰或横滚就能翻过来。不需要掐时机。摇杆回中，然后起飞。",
"1ri6cg": "这是什么",
"14tfw5g": "打开它",
"1eqzli7": "穿越机，弹射起步，开。不打开就一直是关的。然后在起跑线上、推油门之前按 L。",
"14cfpm3": "设定角度",
"11n5q78": "油门怠速。向前压俯仰，直到 OSD 显示大约 30 到 40 度。摇杆回中。电机会保持住。",
"1aa3oyb": "把油门猛推过大约百分之 20。保持解除，桨叶抓住空气，你就飞出去了。起步后再按 L 可以重置。",
"14arqvb": "上箭头是向前俯仰。W 是油门。弹射起步在保持期间把你切到 Acro，出发后恢复你自己的模式。",
"r89zwp": "和真实飞控的步骤一样。L 是模式开关。可以在穿越机下的固件工作台里微调 launch_angle_limit 和 launch_trigger_throttle_percent。",
"1wrrqt3": "如果在起跑位上翻倒，TURTLE MODE 会接管。打俯仰或横滚翻过来。不需要掐时机。摇杆回中，然后按 L 再次起步。",
"1x7j2uc": "弹射起步，如果你在穿越机里打开了它。前倾，回中，猛推。",
"1xmpyfk": "在飞行中切换 Angle 和 Acro，并记住这个选择。",
"1eyul69": "R，然后 Escape",
"1ns2uml": "回到起跑线，并暂停。",
"1hg0wdz": "如果你倒扣在地上，会出现 TURTLE MODE 提示。用方向键打俯仰或横滚就能翻过来。不需要掐时机。松开，然后起飞。",
"19jaz7h": "报告错误或提供反馈。如果你在空中会先暂停，然后打开表单。",
"1ogqofk": "触控区在飞行中出现，就在你的拇指下面。",
"1harh8g": "动一动摇杆。这些会跟随遥控器。",
"149s8uu": "L 让它就绪。前倾，回中，猛推。云台摇杆仍然跟随你的手。",
"rt9bay": "按键试试。这些会跟随你的手。",
"utog3i": "拇指摇杆是真正的比例摇杆，所以用的是穿越机里设置的飞行模式：默认是 Acro，和遥控器一样。学习时 Angle 更温和：松开右触控区，穿越机就自己回平。",
"1uqyqut": "遥控器默认飞 Acro：摇杆要求的是转动速率，松手就是要求不转，于是穿越机保持当时的姿态。可以在穿越机的飞行模式里更改，或者飞行中按 M。",
"wtsp1v": "默认关闭，因为从保持状态猛推很猛烈，不是每个人都想要。在穿越机里打开，然后在起降垫上按 L。绿色的 LAUNCH 读数是俯仰角。油门快要触发时它会闪烁。",
"t0ww0i": "按键只有开和关，所以按住的时间就是模拟量：轻点让摇杆动一点，按住会停在一个好飞的量，长按到满杆。键盘竞速从 Angle 开始，所以松开按键穿越机就回平。",
