"1lrz4zo": "拇指在玻璃上的行程大约只有云台摇杆的四分之一，而且没有回中力，所以下面的数字比遥控器默认值更柔和。横滚、俯仰和偏航在你抬手时回弹；油门留在你放开的位置，和遥控器一样。",
"iulg1q": "按键不是摇杆。按住时摇杆会升到百分之 34 并停在那里，直到大约四分之三秒，然后在一又四分之一秒时伸到满杆。所以下面的 Rates 是遥控器飞出来的 Rates：轻点一下只能达到其中大约三分之一，这就是键盘飞行比数字看起来更硬、起效更慢的原因。手柄或 USB 摇杆模式的遥控器能用到整条曲线。而键盘竞速从 Angle 开始，它不理会这条曲线：穿越机下的键盘竞速，或飞行中按 M，可以切到 Acro。",
"j83vdk": "正在等待遥控器上报。动一下摇杆。",
"pc5ckr": "你的遥控器每秒刷新 {0} 次。无论如何 Betaflight 都按固定的 250 Hz 帧网格飞行，所以这表示每一帧上的值有多新。",
"tn3t15": "这就是你的帧率，每秒 {0} 次，说明这个浏览器每画一帧才读一次遥控器。前馈作用于帧与帧之间的变化，所以每帧只跳一步的摇杆感觉像一连串轻推，而不是一次推动。下面的 Rates 改不了这一点。",
"1iahfwq": "这个遥控器在摇杆全行程上大约上报 {0} 级，粗到在高 Rates 下能感觉出来。换一个 USB 上报更细的遥控器，或者降低 Rates，都能缓和。",
