"ha6vhk": "加油门：你在下坠。",
"gfb2fb": "太高了：收一点油门，回到场地上方。",
"dx5xtd": "还是太高。降下来，或者按 R 从起降垫重新开始。",
"1npdmku": "还是太高。降下来，或者从暂停菜单重新开始课程。",
"amu0ck": "回到起降垫。在场地上方保持低飞。",
"1cb4ot5": "刹车环：以低于 {0} km/h 穿过。",
"gutnb6": "高速环：以高于 {0} km/h 穿过。",
"p7oikr": "太高了：收一点油门。",
"8mjdka": "再高一点：加点油门。",
"kxrljr": "回到标出的区域里。",
"1vutx5w": "慢下来：在里面稳住不动。",
"15r1rd7": "再次起飞。",
"iwhoeq": "太重了。起飞后轻轻降下来。",
"119tq": "不在起降垫上。起飞，降落在亮着的那个上。",
"9fjzpj": "向左转：{yaw}向左。",
"66oahr": "向右转：{yaw}向右。",
"139fmqe": "再次起飞：在起降垫上方低空悬停。",
"1paaito": "回到起降垫上方。",
"15ousot": "再大一点：你离得太近了。",
"8mgocf": "再小一点：靠近中间。",
"9mvdlz": "再高一点。",
"mymysj": "先爬高一些。",
"dqbmn": "再快一点。",
"1idviqd": "再高些。做动作前多爬一点。",
"zq4fgo": "做干净：一次平顺的旋转。",
"1a7n153": "那是{0}。课程要的是{1}。",
"7uesfl": "不是那个。再读一遍目标。",
"1ikowyg": "再高些。开始前多爬一点。",
"1qgbgyr": "两个半圈之间停一下：数“一”，再继续。",
"181mx3x": "横滚半圈，停住，再横滚半圈回来。",
"wk4p7r": "同一方向两个半圈，中间停一下。",
