"15j6il5": "Nick Burns 的家",
"1q6n65k": "用圈圈机飞 Nick Burns 的家：每个房间、楼梯、车库、藤架、泳池和街道。",
"1sj355l": "Heads 的家",
"g5fs7c": "Infinity Loops 制作的 Heads 的家，用圈圈机飞：车库、地下室、楼梯、每个房间、院子和街角。",
"1xzcsy8": "Joshua Bardwell 的家",
"1yy0wqt": "用5寸机飞 Joshua Bardwell 的家：砖房和门廊、柴棚、围栏、车道、场地上的笼子，以及穿过这一切、翻过山脊再回来的比赛门。",
"uiqj1x": "用圈圈机飞 Thomas More's Shop：卸货门、通往白色办公室的木箱通道、木皮卷下方的 Barani 门洞、车间、喷漆房和机器房。",
"1dil1q8": "Heads 的整个街区，用圈圈机飞，每一位 90%er 都有一只山羊在里面游荡。低飞赶羊，把每只山羊都赶进 Heads 敞开的车库。",
"cp5v17": "用5寸机飞 Sunnyfield：主街、巨型甜甜圈、钟楼、峡谷、发电厂和冷却塔、有大房子的山丘、垃圾场、水塔和滑板公园。",
"15bujc4": "樱花下的漂移祭。追走对决全天在赛道上进行：你就是摄影机。追着赛车，把它们保持在画面中央，让两辆车同框，并在贴点区拍下决定性的镜头。",
"159ros3": "一座泛光灯照亮的竞技场，两端各有一个球门，还有一个汽车那么大的球。把它推进对方的球门。",
"1rlg3xu": "放学后的学校，用圈圈机飞：走廊、教室、理科实验室和玻璃水槽、图书馆、通风管和运书升降机。感染模式就在这里玩。",
"1yuj7c2": "山脊上的越野摩托赛道。十辆摩托在上面飞驰：弯墙、搓板路、平台跳和双跳，甩尾过弯，每个跳台都来一个 whip。你就是摄影机。追着车群，把一名车手保持在画面中央，抓拍 whip。",
"17xknr1": "围绕车站街区的街头漂移活动：穿过高速路下方，两次穿过铁轨下方，绕过出租车环岛和加油站。追着追走车队，或者去飞拱廊、停车场和站台。",
"1q67y6n": "日本海边的沙丘海岸，用5寸机飞：在大沙脊上冲浪，沿滑落面俯冲到池塘，穿过防沙栅栏、骆驼棚和缆椅，并在十二道竹门间竞速，从瞭望台到海边再回来。",
"1fertyq": "夜晚的集装箱码头：堆叠集装箱形成的峡谷、停泊货轮上方的三台岸桥、砖砌仓库、大门和港口塔。漂移车在停机坪上奔跑。",
"1gqg4t1": "用5寸机飞 Hamakaze Works：炼钢车间和吊车、管架和管桥、皮带廊道、球形储气罐、储罐区、控制楼、红白相间的烟囱和码头上的龙门吊。",
"1kgnyvt": "岩石岛上的海滨度假村，已关闭多年。贴着酒店阳台扫过，俯冲楼梯井，穿过海蚀柱和拱门，并在公园里竞速十道门。",
"1ithhdl": "日本阿尔卑斯山脉的一条高山脊。从垭口俯冲南壁，在索道塔之间回旋，穿过山间小屋，再降到湖面，飞越大坝溢洪道的缝隙。",
"1yboohq": "一座用来俯冲的高塔之城。从最顶端的双子塔冠、一座带洞的空中花园、两座塔楼之间的窄缝、两台塔吊下正在搭建的钢架、高速路、高架桥，以及这一切之下的老巷子。",
"gmm0ht": "一座泥地穹顶场馆，四辆怪兽卡车在屋顶下飞跃汽车和巴士。追着它们越过坡道，穿过屋顶桁架，贴着看台扫过。",
"1mdza0j": "雪松林中的废弃温泉旅馆，用5寸机飞：可以回旋穿行的成排雪松、旅馆和浴场、仓库、砖烟囱、一排鸟居和一条鸟居隧道、小溪和桥，以及台阶上方的神社。",
"1gkf4rj": "下班后的商社，用圈圈机飞：楼下的货架、销售层的办公桌岛和会议隔间、楼上的董事会议室和社长室、从顶层直通地面的空电梯井，以及屋顶。",
"ehnw9b": "初雪时节的北海道平原，用5寸机飞：穿过四道空中之门爬升穿越热气球集会，穿过冬季集市的灯光隧道和摊位缝隙，飞过红色谷仓和筒仓，沿白桦大道向北巡航一英里，到达古老的拱形高架桥和风力发电机。",
"156ap15": "山丘上的废弃疗养院。飞过长长的走廊，从窗到窗横穿病房，俯冲屋顶的破洞，穿过钟楼，并在杂草丛生的院子里竞速十道门。",
"1hmr2w6": "梯田山坡下的一条柏油加砂石的拉力跨界赛道。六辆赛车在上面比赛，横着滑过发夹弯，在跳台上飞得很远。从上方追着它们，穿过看台屋顶，找出缝隙。",
"1ps9pev": "城堡公园里的自由式越野摩托表演。车手们从两个跳台飞越祭典鼓楼，做出空翻和 whip，两侧是看台，护城河对面是天守阁。跟着他们飞出坡道，拍下动作。",
"w2yh22": "山谷里的一条草地跑道：从前到后飞过拱形机库并穿过它的椽子，还有水田、雪松、塑料大棚、红桥下的水渠，以及绕这一切飞行的十四道门。",
"1yeqk86": "日本乡间的一座山谷：水田和晒稻架、茅草农舍、水车磨坊、带鸟居隧道的神社、上山的梯田、城堡遗迹，以及海中立着鸟居的渔港。",
"mgpu3l": "秋天的山口公路。层层叠叠上山的发夹弯、可以追的汽车、山脊下的隧道、峡谷上的红桥，以及山顶的茶屋。",
"1xepshq": "堤坝下河滩上的无人机竞速节。一圈十六道门、维修区、主舞台、小吃摊、水闸和跨河的铁路桥。",
"9y2g5d": "流冰中的冬季岛屿。穿过冰山拱门，贴着浮冰飞，在瀑布旁的悬崖俯冲，找到瀑布后面的洞穴，并环绕海角的灯塔。",
"v0wjg": "城市中心的废弃住宅小区：楼板正在塌落的五层楼、敞开的楼梯塔、通往旧商业配楼的天桥、带支腿的水箱、锅炉房和铁路高架桥。十二块橙色标牌标出一条穿过它的比赛路线。",
"s8yjkr": "秋天山间的赛车场。GT 赛车全速绕圈：在直道上追它们，穿过维修车库、看台屋顶和下方的隧道、桥、巨型轮胎和摩天轮。",
"154p7c7": "黄金时刻的城市公园：棒球场和挡网、球员席、池塘和太鼓桥、游乐场里的章鱼山、角落里的神社和周围的小巷。",
"18a1m0y": "黄金时刻的主题乐园。追着 Ryusei 过山车爬上提升坡、穿过环道、冲进龙口，穿过大摩天轮的轮辐，和跳楼机比谁落得快，再飞过城堡大门和鬼屋。",
"13fchbi": "黄昏时分的舞曲音乐节。高台上的 DJ、LED 墙、数千名观众、中央的调音台、延时音箱塔、摩天轮，还有舞台上空的烟花。",
