"cyw1pe": "一款浏览器 FPV 竞速模拟器。飞控是 Betaflight。赛道语言来自 Track Draw。其余的，来自一位飞手和那些一直飞到手感对了的人。",
"1sncokl": "制作",
"kai17": "制作了这个模拟器、编辑器和公共榜单。一路上指挥了一大群 Grok 和 Claude。",
"1rju5ni": "合作伙伴",
"10ax242": "他们支持 WebFPV。",
"1fpu7yw": "Beta 测试飞手",
"2sef6d": "他们一直飞到它感觉像一台真正的穿越机。",
"lq4qk4": "飞控",
"152d3mr": "Rates、PID 环、滤波器、前馈、TPA、iterm relax、airmode、anti-gravity。是编译进这个页面的，不是重写的。",
"kfh8vm": "是 GPLv3，所以本项目也是。飞控界面致敬的是",
"1ol0nlq": "10.10：标签页名称、4.5.1 的字段，以及经典的深灰配橙色。它不是那个应用。没有 Vue，没有 MSP，没有 iframe。感谢 Betaflight 的开发者们。",
"kwollz": "赛道语言",
"91xq6y": "编辑器的灵感来自",
"1v1kv66": "，出自荷兰的无人机大神们：",
"1ffizjn": "RaceGOW5 房间",
"ov7ihs": "八条赛道，六位建造者，根据官方动画还原。",
"f0ewtp": "系列与动画：",
"432t9y": "大军",
"gw6sa5": "与 Grok 一起写。与 Claude 一起建。",
"1m26mn1": "xAI 的 Grok。贡献了许多代码行、许多争论，以及对飞行手感的许多固执。",
"1i8y2kj": "Anthropic 的 Claude。大军的另一半。握着摇杆的还是同一个人。",
"sskqzq": "Betaflight、Track Draw、Grok、Claude、Dutch Drone Squad 及其标识归各自所有者所有。频道图片归各位飞手所有。在这里使用它们是致谢，并不表示他们为本页面背书。合作伙伴的标识归合作伙伴所有，经其同意展示。WebFPV 是自由软件，许可证为",
