"1g3lqvf": "还没有遥控器或手柄传到此浏览器。接上它，设为摇杆模式并动一下摇杆：只有上面有东西动了，浏览器才会把手柄给页面看。",
"l55p9d": "你保存的校准从这个手柄没有的轴上读取{0}，所以{1}读不到任何东西。它有{2}。校准摇杆会按它实际发送的内容重新映射。",
"10cte0": "轴 {0} 像摇杆一样在动，但模拟器里没有东西读它。浏览器收到了你的摇杆；模拟器把它放在了错误的通道上。校准摇杆大约一分钟就能修好。",
"13f86ul": "轴 {0} 在动，但模拟器里没有东西读它。如果那就是不工作的摇杆，校准摇杆会把它放到正确的通道上。",
"3hxjne": "那是{0}，在轴 {1} 上，并且已经传到模拟器。",
"4pid3q": "{0}像摇杆一样动了，但模拟器里没有东西读{1}。这是摇杆在错误的通道上，校准摇杆可以修好。",
"13inlwb": "把不工作的摇杆推到两端的尽头，同时看这些条。",
"2niqw0": "在遥控器上：打开本页之前，插线时选择 USB 摇杆模式，并检查上面选中的模型。模型决定每个通道发送什么，新的或空的模型可能在某个摇杆上什么都不发。",
"jem3gg": "你的遥控器以 {0} 个轴的形式传入。",
"rr1z7d": "如果没有条在动：Windows",
"1j91r00": "检查 Windows 是否能看到摇杆：按 Windows 键和 R，输入 joy.cpl，按 Enter，选择你的遥控器并打开属性，然后动一动它。如果那里会动而这里不动，请从这个界面报告 bug 并说明情况。",
"1qj9g8y": "如果那里也不动，说明遥控器没有发送它。在那个 Windows 窗口里校准不会改变浏览器读到的任何东西，所以没必要做。",
"1elsn67": "如果没有条在动：Mac",
"193sfmd": "macOS 没有自带的摇杆测试，所以这些条就是测试。如果某个摇杆在一个浏览器里会动而在另一个里不动，请从这个界面报告 bug 并说明是哪个。",
"1lg87ci": "如果没有条在动：Linux",
"fk484m": "jstest-gtk 或 evtest 能显示遥控器在发送什么。如果摇杆在那里会动而这里不动，请从这个界面报告 bug 并说明情况。",
