"yajn08": "{0} 寸赛道",
"1e05oqz": "在空场地上打开编辑器。画布上原有的内容会保留在它的加载列表里。你搭建的赛道保存在这个浏览器里。清除数据或换一台设备，就得从零开始。发布赛道就能把它放到公共榜单上。",
"1cdhqo": "Betaflight 默认",
"1dudsha": "WebFPV 出品",
"cuy5ed": "改动其中任何一部分，你就到了另一个榜单。",
"1iryycr": "Betaflight 自己的调参，稍加调整：对摇杆的响应快一点，停下后的回弹少一点。打开调参，在那里选择调参，并用 Betaflight 自己的滑块调整。你的 Rates 会保留。",
"k6akiz": "花飞地图",
"10ufhmj": "{0} 寸",
"1r6qcm": "轻微",
"3sm2ze": "强烈",
"1xnvdto": "一架全尺寸的花飞和竞速穿越机：相对动力来说很轻，非常快，还有一片大到用得上它的场地。每架机体都有自己的调参、PID、电池、重量和相机：更换机体会带回那台机器你上次留下的设置，第一次则是出厂设置，并让编辑器在户外场地和客厅之间切换。你自己的 Rates 会跟着你走，除非它们还是出厂的。",
"53x6f3": "粘贴来自榜单或其他飞手的分享码。你会先看到里面有什么，而且可以恢复自己的。",
"9ww08a": "总倍率",
"1vv9xkm": "跟随，P 和 I",
"fetog5": "漂移和晃动，I",
"kyk48v": "阻尼，D",
"1roremq": "动态阻尼，D max",
"1e0pboe": "摇杆响应，FF",
"we45r2": "俯仰跟随",
"1dlny13": "俯仰阻尼",
"1b1bac5": "下面的一切都属于这个调参，每个调参各自保存调整。",
"193v7i": "全部一起调：P、I、D 和前馈一起缩放，比例不变。这就是“调硬一点”的旋钮，也是飞行手感反馈里要的那个。出厂值是 {0}；以前这里附带的偏硬预设是 {1}，差不多就是那些反馈想要的幅度。",
"c3fbrt": "穿越机追随摇杆所要求的角速度有多用力。低则懒散平滑，高则迅速贴上目标值并保持住。",
"amoq3u": "单独的慢误差项。太低会在大动作中姿态漂走；太高会在长时间打杆时积累，并在摇杆回中时以一次抽动释放出来。在这个模型上，抽动远比漂移来得早。",
"1kt9nne": "抵抗旋转，让停止更平滑，平息桨洗流。在真机上，D 的代价是电机发热和陀螺仪噪声；这个模型的陀螺仪很干净，所以阻尼几乎没有代价，偏硬的调参会把它开得很高。",
"1wqluz6": "在快速动作和停止时，在基础 D 之上额外加入多少 D。零则 D 保持不变。",
"10nibr2": "前馈在误差出现之前，直接对摇杆的移动本身施力。高则立即响应；太高会在每个动作开始时过冲。零则只靠 P 和 D 飞。",
"i42c2o": "俯仰的 P 和 I 相对于横滚的比例。穿越机长大于宽，所以俯仰通常多几个百分点。",
"1a9uio": "俯仰的 D 相对于横滚的比例，原因和俯仰跟随一样。",
