"bw3a2g": "把下面的数值起个名字保存，一按就能调回来，这正是飞第二条赛道时需要的。预设只保存在这台设备的这个浏览器里。清除网站数据、隐私窗口、换浏览器或换设备，都会让你从零开始，没有账号，也不会上传任何东西。",
"g0jyc7": "穿越机对小幅打杆的响应有多快，也就是曲线在中间处的斜率。",
"idjhb0": "低则沉稳，适合平滑的路线；高则灵敏、迅速。",
"3gavi2": "它不是半杆时的角速度：请看曲线。",
"1mlk7hb": "Configurator 把这一列叫作 Center Sensitivity。",
"1998vtg": "穿越机在满杆时的表现，分毫不差。",
"njxqki": "Actual Rates 就是为这个数而存在的：不管 Expo 怎么改变中间，曲线末端就是你输入的数。",
"1x3rl5q": "行程中有多少用在中位附近。零是从中位灵敏度到尽头的一条直线。调高会让中间变软而最大值不变，所以改动它时曲线两端不会动。",
"7xrlm4": "让油门在中点附近变平、两端变陡，与 Betaflight 的 thr_expo 完全一致。{0} 是出厂的直线。",
"h1vu9t": "给这些数值起个名字，一按就能调回来。预设只保存在这台设备的这个浏览器里。清除网站数据、隐私窗口、换浏览器或换设备，都会让你从零开始，没有账号，也不会上传任何东西。",
