"12fqnbp": "楼房",
"1v2ux9n": "一栋公寓楼、写字楼、仓库，或楼上有住宅的店铺。屋顶可以降落。给它加一条通道，就能在底层打通一条拱廊。",
"wnu4ob": "废楼",
"1buzq6l": "一座废弃的混凝土框架：柱子、整跨缺失的楼板、带洞的墙、楼梯间。每一处缺口都是一条路线。破损度决定缺掉多少；变体会换成另一种废墟。",
"1hf20yb": "塔吊",
"q0p394": "一台平头塔吊。吊臂指向你面对的方向。桁架的每根杆件都是实体，起重钢绳也是。",
"mdyszh": "水塔",
"1jn5ant": "四条带斜撑的腿上架着一个水箱，周围有一圈走道。从腿之间飞过，绕着水箱转。",
"18evknm": "桁架塔",
"vgz6jn": "一座红白相间的无线电塔，三角桁架，顶部有天线。",
"13k3kqc": "烟囱",
"1ubvyw9": "一根上细下粗的砖烟囱。就是那个可以绕着飞的高东西。",
"evxs7t": "空心烟囱",
"dpno39": "一根可以往下飞的砖烟囱：顶部敞开，在你面对的一侧底部有个门洞。越过边沿俯冲进去，再从门洞出来。门洞的宽度不会超过半径的一又四分之一。",
"1de4mby": "输电塔",
"1maryws": "一座桁架输电塔。电线连到最近的另一座塔，不是实体；塔是实体。",
"1c1mwes": "风力发电机",
"etuwq": "一台三叶片风机，停着不转，转子朝向你指的方向。塔筒、机舱和每片叶片都是实体，叶片不转：转子决定它们停在哪里，从 0 到 1 是三分之一圈。叶片不会比轮毂的高度更长。",
"enckx": "集装箱",
"1rrvj0h": "一摞海运集装箱。敞开样式会让最底下那个空着并去掉两端：一条隧道。竖起来就是一口可以俯冲下去的竖井。",
"4nq0fz": "脚手架",
"r2tkkr": "钢管加踏板，每两米一层。踏板之间是一条贯通全长的隧道。",
"1nybcq8": "桥",
"njf6r6": "架在桥墩上的立交桥，或两端带台阶的人行天桥。桥面可以降落；桥下的空间就是路线。",
"1acbmdg": "广告牌",
"meudfk": "两条腿撑起的广告牌，带一条检修走道。牌子下面的缝隙是一条路线。变体会更换广告。",
"1732grf": "电线杆",
"1m8tesi": "小镇的水泥电线杆。电线连到 45 m 内最近的另一根杆；它们不是实体。",
"bm4v9g": "路灯",
"1rql6uz": "一根灯杆，灯臂伸向它面对的方向。",
"1meblmn": "自动售货机",
"g1vg8s": "小镇自己的饮料机，朝向你指的方向。",
"eei68u": "停着的车",
"9gjenp": "小镇里的一辆停放车辆，车头朝向你指的方向。变体会更换颜色，或 r32 和 e82 的涂装。",
"39zqc9": "栏杆",
"93axb6": "架在立柱上的一根圆杆。贴着它飞。",
"rolt1y": "台沿",
"1d396rc": "一段正面带钢边的混凝土台沿。竖起来就是一块板，高度和长度一样。",
"sbni0y": "楼梯组",
"li9vsd": "一段带扶手和平台的台阶。最下面一级朝向你指的方向。",
"1gaz02h": "四分之一管",
"m2knek": "一段弧面加一个平台，弧面朝向你指的方向。",
"1tyhj3p": "树",
"wy2gyj": "一棵樱花树、行道树或松树，按小镇的画法画出来。树冠是实体。",
"1vvvm1h": "风车",
"19jtx1c": "一座塔式风车，四片风叶会转，面对它时是逆时针。风叶是实体，塔身也是：掐好时机从两片风叶之间穿过，或从风叶和塔身之间飞过。速度是每分钟的圈数，0 会让它们停在转子设定的位置。它只朝向东南西北四个方向，因为风叶要在物理能跟上的平面内转动。",
"l2lhse": "命名缝隙",
"10vfjdf": "一个看不见的计分窗口，就像滑板游戏里的 gap。给它起名，选好分值，把它放在路线经过的地方。飞过它就得分。",
"1v8qqqq": "追气球",
"zijmud": "一架轻型飞机在地图上空飞出干净的路线，一路放出气球让你戳破：每回合九十秒，金色的值三个，最好成绩按地图保存。它绕着这个点飞，最远到半径，不会低于高度，前面有东西挡路时会飞得更高。速度决定它飞多快。它没有任何实体部分。每张地图一架；第二架不会飞。",
"1wq5fn7": "5寸机竞速",
"cvgrbe": "一条建在{0}上的竞速赛道。MultiGP 的门、旗和俯冲门摆在以米为单位的网格上，用5寸机飞，并发布到榜单。",
"x74gv0": "榜单",
"62dlbi": "圈圈机竞速",
"kwsd3j": "给圈圈机的房间。在{0}里摆上 RaceGOW 的 28 英寸门，网格以英寸为单位，并由 RaceGOW 自己的规则检查布局。",
"pcduke": "在{0}上建一张属于你自己的地图。楼房、吊车、滑板道具和命名缝隙，想放哪就放哪，用5寸机飞，没有门也不计时。",
"1q0lzfa": "没有门",
"1p0yqlf": "把这张地图连同赞助商印花一起放到公共榜单上",
"3ph5ii": "顶栏",
"1t58w8i": "底栏",
"1yalzrl": "那根立柱",
"vuco": "标准",
"br5vti": "常用大小，大约 1 到 2 MB，哪里都能发。大约一分钟。",
"1gq8xlp": "高",
"ezfzh6": "像素是四倍，所以线条和文字在大屏幕上依然清晰。文件大约是标准的两倍半，耗时大约三倍。",
"vlhosf": "超高",
"1deatko": "像素是标准的十六倍，适合海报或投影仪。文件大约七倍大，长的一圈约 6 MB，超过一些聊天软件的上限，耗时大约十几倍。它需要一台显卡不错的电脑，手机或小平板可能应付不了。",
"ygbbbe": "黑色舞台",
"ljr78o": "赛道放在黑色地面上，一直以来都是这么拍的。",
"6yrwjd": "竞速场地，草地上有赞助商",
"snd8gp": "赛道放在条纹草地上，和游戏里的样子一样，赞助商的标志画在你放的位置，门和旗上也有，上面不带名字。文件更大，因为草地不是黑的。",
"13qp3n0": "和图纸一样",
"19q6chm": "从图纸下边缘向上看，所以赛道的走向和你搭建的一致。",
"1dvsiya": "起点后方",
"cvgqu": "从起点后方沿第一段看过去，就是起跑线上飞手看到的样子。",
