"4s2yr8": "已选中{0}。Delete 只拿掉那根管子：开口仍然计分，也仍然会亮。Esc 取消选中。",
"v5arju": "已拿掉{0}。开口仍然计分。在检查器的框架里把它放回来，或者撤销。",
"tz7po4": "这在路线上放下了一个航点，它会让路线弯曲，但不计分。两侧的门保持原来的朝向；检查器里的{0}可以把它交还给自动规则。",
"1ebxdxc": "点按{0}来放置。它会留在手中等着放下一个，工具栏上的工具可以把它收起来。",
"1ua7ifj": "尺子在 3D 中测量，可以斜着看，也可以从上方看。按 V，或工具栏上的 3D。",
"15onv1j": "在工具下方选一个字母，然后点击{0}。字母里的每个空隙都是一道可以穿过的门：W 在两个 V 之间有一个，B 有两个。",
"r5y8ck": "点击来放下道路的节点：它会像车能开的那样沿节点弯曲。点击第一个节点可以闭合成环，按 Enter 或双击以开放状态完成，Escape 停止。",
"1lzs3aa": "点击道路可以在那里放一辆车。在双车道环路上，你点击的那一侧就是它行驶的车道。",
"qwmr1o": "车辆要在道路上行驶，而这张地图还没有道路。先用道路工具铺一条。",
