"aet9cy": "环路需要 {0} 个节点。",
"tvaqrx": "道路需要 {0} 个节点：点击它接下来要去的位置。",
"1xk4hcq": "道路已铺好。拖动节点可以改变形状，拖动两个节点之间的旋钮可以加一个节点，点击节点再按 Delete 可以去掉它。选择车辆并点击道路，就能在上面放一辆车。",
"ogb731": "道路需要两个节点。请改为删除道路本身：点击远离节点的位置，再按 Delete。",
"1xp7uwj": "两个节点无法闭合成环，所以道路现在是开放的。",
"1hudr1b": "车辆要放在道路上：点击一条道路，或紧挨着它的位置。",
"1vqxq39": "一张地图只有一组起飞垫，也就是飞手出发的地方，所以这次移动的是你已有的那组。",
"b9600b": "一条赛道只有一组起飞垫，所以这次移动的是你已有的那组。",
"1wr6pa0": "每个洞都是一道独立的门。这一叠是螺旋上升：底部，绕一圈，然后顶部。在{0}里修改。",
"co4ov2": "一个路段就是普通的部件，按铺设顺序飞。像其他部件一样移动、旋转或调整大小，或者按撤销，换一个形状重新铺。",
"n9k3yi": "隐形门和任何门一样计分、一样会亮，但周围什么都没建。在房间里，只有当它是下一道门时才会亮。像门一样调整大小、旋转和飞它，卡片上的框架可以把管子放回来。",
"142x321": "角度是相对于这一圈飞越栏架的路线而言的，所以栏架得先被飞过：飞越会让这一圈经过那里。",
"1tt8aac": "墙门是共用立柱的几道门，连成一体。每一跨都是单独的一次穿越，以穿梭方式飞：卡片上写着方向，也可以修改。",
"1fnwagm": "那道门现在是{0}了，位置不变，在飞行顺序里的位置也不变。卡片上的字母可以把它换成别的，变成门可以把它变回去。",
"1y4yt13": "这比字母自身的管子还小，所以就没有可以穿过的空隙了。",
"13tvely": "旗子随框架一起去掉了：桅杆上的三角旗如果什么都不围着，就会悬在半空。",
"hdt67k": "现在是一道门了：穿过任一开口都算，轮到它时两个都会亮。在卡片上把它拆开即可还原，或者按撤销。",
"tjm182": "这些门又分开了，一道接一道地飞。",
"1yf9hh0": "那道门不能挂一面用来绕飞的旗。请改为绕它旁边的一面旗飞。",
"2nb4dg": "那根立柱上挂了一面旗，所以有东西可以绕了。旗可以移动或去掉它。",
"n0y7i6": "路线进门时已经经过那面旗了，所以没有东西可绕。螺旋下降或螺旋上升会绕它一圈。",
"aohk6f": "飞行路径接在一道门或一面旗的后面、里面或周围：它们是一圈要飞的部件。",
"2zkq78": "门的那一侧没有旗。旗可以在那里放一面。",
"iy6dnt": "那个花式要接在一次穿门之后。",
"1ds4m80": "一张地图只有一组起飞垫，所以它们不会被复制。",
"rx31yk": "起飞垫没有包含在副本里：一张地图只有一组。",
"1hj67dr": "建造物立在它下面的东西上，所以它没有可以逐级抬离地面的高度：把它放在它该立着的屋顶或集装箱上。Page Down 会把地面上的物体沉入地面，而命名缝隙有自己的高度，两个键都能调。",
"1j8hizs": "手里拿着{0}：点按要放的位置。在这里打开调色板再点一次{1}就能把它收起来",
"1ecey5p": "拖动竞速线可以让它弯曲：这会在上面放下一个航点。再按一次弯曲路线，点击门就还是点击门。",
"1m6lsky": "从房间中央",
"2lnatw": "桌子、椅子或横幅按四分之一圈旋转：它们由方块组成，并且与房间保持方正。",
"mamvu6": "楼房、集装箱、桥和滑板道具目前只沿东南西北摆放：在物理学会处理转动的方块之前，它们按四分之一圈旋转。吊车、树、桅杆和门可以自由旋转。",
"4l5z1f": "对齐开：新的门、墙门、栏架和上升门朝向最近的轴并保持不变。用 Q、E 或旋转栏来转动。按住 Alt 可以脱离网格、不对齐地放置。",
"r7sd0l": "对齐关：新门沿着与前一道门的连线朝向，角度任意，赛道变长时工具会重新计算朝向。",
