"1cy6t48": "每个开口",
"4ikah4": "叠门的每个开口都是一道独立的门：给它自己的宽度和高度，比赛会按那个开口自己的尺寸来判定每次穿越。你没动过的开口用的是上面叠门的尺寸。",
