"h5sgwm": "在主空隙的位置放一道同样大小的普通门。对其他空隙的穿越会从顺序里去掉。",
"q7q9fq": "框架",
"r64mng": "管子被拿掉：空隙仍然会判定并亮起，而且没有可撞的东西。它在房间里只显示空隙。",
"s9vozj": "这个字母是用管子搭的。把它变成隐形，就能保留它的空隙作为目标，周围什么都不搭。",
"1rkao2q": "把管子装回去",
"1ezapez": "变成隐形",
"1h88uzq": "每一边都是单独的管子：上横杆在最上面的开口之上，下横杆在最下面的开口之下，立柱则是每个开口一段。左和右按钮拿掉整根立柱；它们下面的按钮拿掉一个开口的那一段。拿掉之后开口仍然会判定。在 3D 视图里，点击选中门的一根管子再按 Delete：只会拿掉你点的那一段。左和右是面对门时看到的方向，和顶部旗一样。",
"3wzvo0": "每一边都是单独的管子。拿掉一根，开口仍然会判定并亮起，那里也没有管子可撞。在 3D 视图里，点击选中门的一根管子再按 Delete。左和右是面对门时看到的方向，和顶部旗一样。",
