"ka4wbv": "把每一边都装回去",
"103wg51": "拿掉每一边，有旗的话连旗一起：开口仍然会判定并亮起，没有可撞的东西。",
"e2847m": "顶部旗",
"127gict": "三角旗在栏架上的位置：在它的两端。旗杆高度就是下面尺寸里的旗高，而且旗杆是实体。",
"17wx66j": "面对门时，三角旗立在上横梁的什么位置。“顶上”会在板的正中、开口正上方立一根旗杆。旗杆高度就是下面尺寸里的旗高，而且旗杆是实体：俯冲向顶杆的飞手可能会撞上它。",
"d0y2y3": "洞",
"1w31kfz": "绿色方框是你必须飞过的空间。在平面图上拖动圆形手柄，可以把它绕着标记转到任何位置，整整一圈都行。“翻转侧”把它送到对面一侧，“重新推算”把它交还给自动规则，也就是转弯的外侧。",
