"1c086it": "没有选中任何东西。点击一个部件来编辑，或者在空地上拖出一个框来选多个。",
"3eggiu": "：RaceGOW，给在房间里飞的 65 mm 圈圈机用。门 24 到 28 英寸，相邻的门中心距 30 英寸，整条赛道在最小门尺寸下不超过 4 乘 6 英尺，并随门一起放大。每个部件都从房间中心以英寸计量，网格为一英寸。",
"1329h41": "：场地上的5寸穿越机。MultiGP 的门尺寸，每个部件都从场地的角以米计量。",
