"19w4clv": "{0}叠放的开口间距为 {1}。相邻的门中心距为 27 到 33 英寸，叠放或并排都一样。",
"1ims1cr": "{0}和{1}相距 {2}。离得这么近的两道门算相邻，而相邻的门中心距为 27 到 33 英寸。",
"8wy7kh": "{0}和{1}相距 {2}。如果它们本来要做成并排的一对，相邻的门中心距为 27 到 33 英寸，标称 30。",
"107lerp": "{0}与{2}的距离为 {1}。杆距门的中心至少 14 英寸。",
"1uyg16": "{0}和{1}相距 {2}。两根杆至少相距 36 英寸。",
"zolwjx": "赛道占地 {0} 乘 {1} m。在这个门尺寸下，RaceGOW 赛道要能放进 {2} 乘 {3} m。",
"4hr5zo": "按 S，然后点击出发的位置。",
"lk5z4a": "这一排还跨了两个高度：{0} 号垫在 {1} m，飞行器的垫在 {2} m，所以垫子都画在 {3} m，有的悬空，有的被埋住。把这一排移到同一个平面上。",
"ls6ln3": "起飞垫跨了两个高度：{0} 号垫在 {1} m，飞行器的垫在 {2} m。垫子都画在 {3} m，所以有的悬空，有的被埋住。把这一排移到同一个平面上。",
"1hy0328": "{0}撞进了{1}：一个穿过另一个搭着。移开其中一个。",
"500wke": "{0}和{1}之间留了一条 {2} m 的窄缝。5寸机需要 {3} m 才能通过，所以要么把它封上，要么把它拉宽。",
"10fprle": "{0}的叶片转动时会扫过{1}。移开其中一个，或者转动风车。",
"h9gzex": "{0}不会飞：一张地图只飞一个追气球，也就是{1}。移除其中一个。",
"ym814r": "{0}的窗口被{1}挡着，所以什么都无法干净地飞过。移动缝隙或者挡在里面的东西。",
"1l0co51": "一个命名缝隙",
"d008ky": "{0}立在地块之外。",
"g0m2mr": "{0}伸出了地块的边缘。",
"np34nj": "{0}完全沉到了地面以下，所以它一点都不显示，也没有任何实体。调高它的底部高度把它升上来。",
"2cz3wz": "这张地图有 {0} 个实体，超过了 {1} 的上限，地图保持在这个数以下才能在慢的机器上流畅加载和飞行。最大的是{2}，占 {3}。",
"1o9p6b3": "在{0}周围，物理要对飞行器检查 {1} 个形状，而它最多检查 {2} 个：其余的会被略过，飞行器在那里可能会穿过它们。把这些部件分散开一些，或者少用几个。",
"36jvfa": "{0}没有道路：{1}。它一直停着，画在地块南边那一排里。把它拖到一条道路上，或者删除它。",
"58628i": "{0}超出了地块的边缘。",
"kof9h3": "{0}穿过了{1}：上面的车会撞上去。移动道路或{2}，直到车有空间通过。",
"1x8yhyt": "{0}压过了起飞垫，所以上面的车会从等待起飞的飞行器身上开过去。移动道路或起飞垫。",
"11r26o9": "{0}经过的地方离飞行器的出发点不到一米，所以上面的车会在飞行器离开起飞垫之前蹭到它。移动道路或起飞垫。",
"e5birv": "{0}穿过了没有起飞垫时飞手出发的位置，所以上面的车会从飞行器身上开过去。移动道路，或者按 S 把起飞垫放到远离它的地方。",
"5s8foe": "{0}和{1}都在{2}上，这是一条开放道路：每辆车都走中间，开到尽头再回来，所以两辆车会迎头相遇并互相穿过。把道路闭合成环路，或者只在上面留一辆车。",
"1c7ews2": "{0}和{1}在{2}的单车道上反向行驶，所以它们会迎头相遇并互相穿过。把道路改成双车道，或者让其中一辆掉头。",
"b92v0l": "给它们相同的最高速度和相同的漂移设置，或者把其中一辆设为倒行，让它走另一条车道。",
"1t8095q": "给它们相同的最高速度和相同的漂移设置，或者把道路改成双车道并把其中一辆设为倒行。",
"ntbmqa": "{0}的起点压在{1}上。把其中一辆沿道路滑开。",
